(function(){"use strict";var FLAG_FR='<svg class="lang-flag" viewBox="0 0 24 16" aria-hidden="true"><rect width="8" height="16" fill="#002395"/><rect x="8" width="8" height="16" fill="#fff"/><rect x="16" width="8" height="16" fill="#ED2939"/></svg>',FLAG_EN='<svg class="lang-flag" viewBox="0 0 24 16" aria-hidden="true"><rect width="24" height="16" fill="#012169"/><path d="M0 0l24 16M24 0L0 16" stroke="#fff" stroke-width="3.2"/><path d="M0 0l24 16M24 0L0 16" stroke="#C8102E" stroke-width="1.8"/><path d="M12 0v16M0 8h24" stroke="#fff" stroke-width="5"/><path d="M12 0v16M0 8h24" stroke="#C8102E" stroke-width="3"/></svg>',LANGS=[{code:"fr",flag:FLAG_FR,label:"Fran\xE7ais"},{code:"en",flag:FLAG_EN,label:"English"}];function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}function buttonsHtml(){return LANGS.map(function(l){return'<button type="button" class="lang-btn" data-lang="'+l.code+'" aria-label="'+esc(l.label)+'" title="'+esc(l.label)+'">'+l.flag+"</button>"}).join("")}function sync(current){document.querySelectorAll(".lang-btn[data-lang]").forEach(function(btn){var active=btn.getAttribute("data-lang")===current;btn.classList.toggle("active",active),btn.setAttribute("aria-pressed",active?"true":"false")})}window.__tfhSyncLangSwitchers=sync;function onClick(e){var btn=e.target.closest(".lang-btn[data-lang]");if(btn){var lang=btn.getAttribute("data-lang");if(lang!==(window.currentLanguage||"fr"))if(typeof window.setLanguage=="function")window.setLanguage(lang);else{try{localStorage.setItem("openfront_lang",lang)}catch{}window.location.reload()}}}function injectSidebarSwitcher(){if(!document.querySelector(".lang-switcher")){var sidebar=document.querySelector("aside.sidebar");if(sidebar){var anchor=sidebar.querySelector(".theme-toggle"),box=document.createElement("div");box.className="lang-switcher",box.setAttribute("role","group"),box.setAttribute("aria-label","Langue / Language");var label=document.createElement("span");label.className="lang-switcher-label",label.setAttribute("data-i18n","lang.label"),label.textContent=window.t?window.t("lang.label"):"Langue",box.appendChild(label);var btns=document.createElement("div");btns.className="lang-switcher-btns",btns.innerHTML=buttonsHtml(),box.appendChild(btns),anchor&&anchor.parentNode===sidebar?anchor.insertAdjacentElement("afterend",box):sidebar.appendChild(box)}}}function hydrateChoiceZones(){document.querySelectorAll("[data-lang-choice]").forEach(function(zone){zone.querySelector(".lang-btn")||(zone.innerHTML=buttonsHtml())})}function init(){injectSidebarSwitcher(),hydrateChoiceZones(),sync(window.currentLanguage||"fr")}document.addEventListener("click",onClick),document.readyState==="loading"?document.addEventListener("DOMContentLoaded",init):init()})();
